begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,other_property uuid,actor_id uuid,competitor_id uuid,input jsonb);
insert into fixture values(gen_random_uuid(),gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid(),'{"action":"create","reason":"Reviewed local competitor details","values":{"name":"Local market fixture","property_type":"multifamily","amenities":[]},"units":[{"unit_type":"A1","bedrooms":1,"bathrooms":null,"rent_min":0,"rent_max":null,"available_count":null}]}');
insert into public.properties(id,org_id,name)select property_id,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision foundation rollback fixture' from fixture union all select other_property,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision other foundation rollback fixture' from fixture;
do $$
#variable_conflict use_column
declare f fixture;r jsonb;payload jsonb;uid uuid;id uuid;v integer;begin select * into f from fixture;
 perform pg_temp.check(not has_function_privilege('authenticated','public.save_marketvision_competitor(uuid,uuid,uuid,jsonb)','execute')and not has_table_privilege('authenticated','public.competitors','update')and not has_table_privilege('authenticated','public.marketvision_decisions','select'),'direct clients cannot forge reviewed decisions or read private evidence');
 perform pg_temp.check(public.save_marketvision_competitor(f.competitor_id,f.property_id,gen_random_uuid(),f.input)->>'state'='forbidden','unknown actors cannot create property records');
 perform pg_temp.check(public.read_marketvision_competitors(f.property_id,gen_random_uuid())->>'state'='forbidden','current property access is required for reads');
 r:=public.save_marketvision_competitor(f.competitor_id,f.property_id,f.actor_id,f.input);perform pg_temp.check(r->>'state'='saved'and r->>'initialUnitsSaved'='1','competitor and initial units save together');
 perform pg_temp.check((select count(*)=1 from public.competitor_units where competitor_id=f.competitor_id)and(select count(*)=1 from public.market_alerts where property_id=f.property_id),'initial records and alert exist together');
 select id into uid from public.competitor_units where competitor_id=f.competitor_id;
 perform pg_temp.check((select rent_min=0 and rent_max is null and bathrooms is null and available_count is null from public.competitor_units where id=uid),'zero prices and unknown fields remain distinct');
 perform pg_temp.check((select count(*)=1 from public.competitor_price_history where competitor_unit_id=uid and source='manual' and available_count is null),'initial price provenance is retained without invented availability');
 perform pg_temp.check(public.save_marketvision_competitor(f.competitor_id,f.property_id,f.actor_id,f.input)->>'state'='replayed'and(select count(*)=1 from public.shared_action_events where id=f.competitor_id),'lost create replies recover one decision and action');
 perform pg_temp.check((select e.origin='console' from public.shared_action_episodes e where id=f.competitor_id),'console decisions are attributed as operator actions');
 perform pg_temp.check(public.save_marketvision_competitor(f.competitor_id,f.property_id,f.actor_id,f.input||'{"reason":"different evidence"}')->>'state'='request_conflict','a request identity cannot overwrite its input');
 perform pg_temp.check(public.save_marketvision_competitor(f.competitor_id,f.other_property,f.actor_id,f.input)->>'state'='request_conflict','same-org properties cannot replay another property decision');
 payload:=jsonb_build_object('action','save','competitorId',f.competitor_id,'expectedVersion',1,'values',jsonb_build_object('name','Reviewed revised competitor'),'reason','Corrected reviewed competitor name');
 perform pg_temp.check(public.save_marketvision_competitor(gen_random_uuid(),f.other_property,f.actor_id,payload)->>'state'='not_found','edits cannot move another property competitor');
 perform pg_temp.check(public.save_marketvision_competitor(gen_random_uuid(),f.property_id,f.actor_id,payload)->>'version'='2','metadata edit increments the current version');
 perform pg_temp.check(public.save_marketvision_competitor(gen_random_uuid(),f.property_id,f.actor_id,payload)->>'state'='stale_competitor','outdated editor cannot overwrite current metadata');
 perform pg_temp.check((select count(*)=1 from public.competitor_units where competitor_id=f.competitor_id),'metadata editor never wipes a saved unit collection');
 payload:=jsonb_build_object('action','save','competitorId',f.competitor_id,'unitId',uid,'expectedVersion',1,'values','{"unit_type":"A1","bedrooms":1,"rent_min":1000,"rent_max":1500,"available_count":0}'::jsonb,'reason','Reviewed current manual pricing');id:=gen_random_uuid();r:=public.save_marketvision_unit(id,f.property_id,f.actor_id,payload);
 perform pg_temp.check(r->>'state'='saved'and r->>'version'='2','unit price update saves with exact version');
 perform pg_temp.check(public.save_marketvision_unit(id,f.property_id,f.actor_id,payload)->>'state'='replayed'and(select count(*)=2 from public.competitor_price_history where competitor_unit_id=uid),'lost price update does not duplicate observations');
 perform pg_temp.check(public.save_marketvision_unit(gen_random_uuid(),f.property_id,f.actor_id,payload)->>'state'='stale_unit','stale unit edits are rejected');
 update public.competitor_units set rent_min=1100 where id=uid;
 perform pg_temp.check((select version=3 from public.competitor_units where id=uid),'provider-side changes also invalidate old operator forms');
 payload:=jsonb_build_object('action','archive','competitorId',f.competitor_id,'expectedVersion',2,'reason','Removed from current competitive set');id:=gen_random_uuid();r:=public.save_marketvision_competitor(id,f.property_id,f.actor_id,payload);
 perform pg_temp.check(r->>'state'='saved'and r->'isActive'='false'::jsonb,'competitor archive is recorded');
 perform pg_temp.check(public.read_marketvision_competitors(f.property_id,f.actor_id)->>'count'='0'and public.read_marketvision_competitors(f.property_id,f.actor_id,false)->>'count'='1','archived competitor remains retrievable outside the active set');
 perform pg_temp.check((select count(*)=2 from public.competitor_price_history where competitor_unit_id=uid),'competitor archive retains all unit pricing history');
 perform pg_temp.check(public.save_marketvision_unit(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('action','create','competitorId',f.competitor_id,'values','{"unit_type":"B1","bedrooms":2}'::jsonb,'reason','Try adding to archived set'))->>'state'='competitor_archived','archived competitors cannot silently receive new manual units');
 perform public.save_marketvision_competitor(gen_random_uuid(),f.property_id,f.actor_id,payload||'{"action":"restore","expectedVersion":3}');
 perform pg_temp.check(public.read_marketvision_competitors(f.property_id,f.actor_id)->>'count'='1','restore returns the retained competitor and units');
 id:=gen_random_uuid();payload:=jsonb_build_object('action','remove','competitorId',f.competitor_id,'unitId',uid,'expectedVersion',3,'reason','Retire invalid manual unit type');r:=public.save_marketvision_unit(id,f.property_id,f.actor_id,payload);
 perform pg_temp.check(r->>'state'='saved'and(select count(*)=0 from public.competitor_units where id=uid),'unit removal changes only the reviewed unit');
 perform pg_temp.check((select jsonb_array_length(before_state->'priceHistory')=2 and before_state->>'rent_min'='1100.00' from public.marketvision_decisions where property_id=f.property_id and kind='unit.removed' limit 1),'removed unit and every prior price observation remain private evidence');
 perform pg_temp.check(public.save_marketvision_unit(id,f.property_id,f.actor_id,payload)->>'state'='replayed','lost unit-removal response remains recoverable');
 perform pg_temp.check(public.read_marketvision_history(f.other_property,f.actor_id,f.competitor_id)->'history'='[]'::jsonb,'decision history cannot leak across properties');
 perform pg_temp.check(public.read_marketvision_history(f.other_property,f.actor_id,null,id)->>'state'='cursor_changed','history cursor is property scoped');
 begin update public.marketvision_decisions set input='{}' where property_id=f.property_id;raise exception 'expected immutable decision';exception when others then if sqlerrm='expected immutable decision' then raise;end if;end;
 perform pg_temp.check((select count(*)>0 from public.marketvision_decisions where property_id=f.property_id and input ? 'reason'),'retained decision evidence is immutable');
end$$;
do $$
#variable_conflict use_column
declare f fixture;bad uuid:=gen_random_uuid();r jsonb;payload jsonb;conf uuid;v integer;begin select * into f from fixture;
 begin perform public.save_marketvision_competitor(bad,f.property_id,f.actor_id,f.input||'{"values":{"name":"Should rollback"},"units":[{"unit_type":"Bad range","bedrooms":1,"rent_min":2000,"rent_max":1000}]}');raise exception 'expected invalid range';exception when others then if sqlerrm='expected invalid range' then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.competitors where id=bad)and not exists(select 1 from public.marketvision_decisions where id=bad)and not exists(select 1 from public.shared_action_events where id=bad),'invalid initial unit rolls back competitor, history, alert, and action');
 payload:='{"expectedVersion":0,"values":{"is_enabled":false,"scrape_frequency":"manual","radius_miles":3,"max_competitors":20,"auto_add":false},"reason":"Reviewed local monitoring preferences"}';conf:=gen_random_uuid();r:=public.save_marketvision_configuration(conf,f.property_id,f.actor_id,payload);
 perform pg_temp.check(r->>'state'='saved'and r->'externalExecutionStarted'='false'::jsonb,'manager settings save does not claim external execution');
 perform pg_temp.check(public.save_marketvision_configuration(conf,f.property_id,f.actor_id,payload)->>'state'='replayed','lost settings save replays without resetting future status');
 perform pg_temp.check(public.save_marketvision_configuration(gen_random_uuid(),f.property_id,f.actor_id,payload)->>'state'='stale_configuration','missing config expectation cannot overwrite an existing row');
 update public.scrape_config set last_run_at=now(),error_count=1 where property_id=f.property_id;
 perform pg_temp.check((select version=1 from public.scrape_config where property_id=f.property_id),'runtime health does not invalidate reviewed settings');
 update public.scrape_config set radius_miles=4 where property_id=f.property_id;
 perform pg_temp.check((select version=2 from public.scrape_config where property_id=f.property_id),'changed worker-side preferences invalidate old forms');
 perform pg_temp.check(public.save_marketvision_configuration(gen_random_uuid(),f.property_id,gen_random_uuid(),payload)->>'state'='manager_required','settings cannot be changed by an unknown actor');
 begin update public.profiles set role='member' where id=f.actor_id;perform pg_temp.check(public.save_marketvision_configuration(gen_random_uuid(),f.property_id,f.actor_id,payload)->>'state'='manager_required','ordinary members cannot change monitoring');raise exception 'rollback role fixture';exception when others then if sqlerrm<>'rollback role fixture' then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.shared_action_events where property_id=f.property_id and (request::text like '%Reviewed local%' or request::text like '%Local market fixture%')),'shared learning history excludes raw private form text');
end$$;
do $$declare f fixture;payload jsonb;identity uuid:=gen_random_uuid();r jsonb;v integer;page1 jsonb;page2 jsonb;begin select * into f from fixture;
 perform public.append_shared_action_event(identity,identity,f.property_id,f.actor_id,'marketvision','console.page.viewed','browser_observed','observed','{"path":"/dashboard/marketvision"}',null,null,'{}');
 begin perform public.save_marketvision_competitor(identity,f.property_id,f.actor_id,f.input||'{"values":{"name":"Must not partially save"}}');raise exception 'expected event collision';exception when others then if sqlerrm='expected event collision' then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.competitors where id=identity)and not exists(select 1 from public.marketvision_decisions where id=identity),'action-history collision rolls back every business mutation');
 for n in 1..23 loop
  select version into v from public.scrape_config where property_id=f.property_id;
  payload:=jsonb_build_object('expectedVersion',v,'values','{"is_enabled":false,"scrape_frequency":"manual","radius_miles":3,"max_competitors":20,"auto_add":false}'::jsonb,'reason','Pagination decision '||n);
  perform public.save_marketvision_configuration(gen_random_uuid(),f.property_id,f.actor_id,payload);
 end loop;
 page1:=public.read_marketvision_history(f.property_id,f.actor_id);page2:=public.read_marketvision_history(f.property_id,f.actor_id,null,(page1->>'nextCursor')::uuid);
 perform pg_temp.check(jsonb_array_length(page1->'history')=20 and jsonb_array_length(page2->'history')>0,'decision history pages beyond twenty records');
 perform pg_temp.check(not exists(select 1 from jsonb_array_elements(page1->'history')a join jsonb_array_elements(page2->'history')b on a->>'id'=b->>'id'),'history pagination does not duplicate decisions');
 perform pg_temp.check(not exists(select 1 from public.scrape_config where property_id=f.property_id and(next_run_at is not null or is_enabled)),'manual disabled preferences have no next automatic run');
end$$;
-- Prove complete reads above the hosted REST default cap, and paginated immutable history.
insert into public.competitors(property_id,name)select f.other_property,'Bulk fixture '||g from fixture f cross join generate_series(1,1005)g;
select pg_temp.check(public.read_marketvision_competitors(other_property,actor_id)->>'count'='1005','complete property reads do not silently stop at 1000')from fixture;
select count(*) as passed_assertions from checks;
rollback;
